ALTER TABLE public.coverages ADD COLUMN supervisor_id uuid REFERENCES public.profiles(id);
ALTER TABLE public.coverages DROP CONSTRAINT coverages_check1;
ALTER TABLE public.coverages ADD CONSTRAINT coverages_identity CHECK ((coverer_type='diarista' AND day_worker_id IS NOT NULL AND employee_id IS NULL AND supervisor_id IS NULL) OR (coverer_type='funcionario' AND day_worker_id IS NULL AND ((employee_id IS NOT NULL AND supervisor_id IS NULL) OR (employee_id IS NULL AND supervisor_id IS NOT NULL)))) NOT VALID;
CREATE TABLE public.absence_treatments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attendance_id uuid NOT NULL REFERENCES public.attendance(id), contract_id uuid NOT NULL REFERENCES public.contracts(id), work_date date NOT NULL, kind text NOT NULL CHECK (kind IN ('dispensa','desconto')), start_time time NOT NULL, end_time time NOT NULL CHECK(end_time>start_time), reason text, authorized_by text, support_doc text, active boolean NOT NULL DEFAULT true, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(kind <> 'dispensa' OR (length(trim(reason))>0 AND length(trim(authorized_by))>0)));
GRANT SELECT, INSERT, UPDATE ON public.absence_treatments TO authenticated;
GRANT ALL ON public.absence_treatments TO service_role;
ALTER TABLE public.absence_treatments ENABLE ROW LEVEL SECURITY;
CREATE POLICY treatments_read ON public.absence_treatments FOR SELECT TO authenticated USING(public.can_access_contract(contract_id));
CREATE POLICY treatments_insert ON public.absence_treatments FOR INSERT TO authenticated WITH CHECK(public.can_write_ops(contract_id));
CREATE POLICY treatments_update ON public.absence_treatments FOR UPDATE TO authenticated USING(public.can_write_ops(contract_id)) WITH CHECK(public.can_write_ops(contract_id));
CREATE FUNCTION public.treatment_before() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.attendance; BEGIN SELECT * INTO a FROM public.attendance WHERE id=NEW.attendance_id; IF a.id IS NULL OR a.status NOT IN ('falta_integral','falta_parcial','ferias','afastamento') THEN RAISE EXCEPTION 'Tratamento exige uma ausência registrada.'; END IF; NEW.contract_id:=a.contract_id; NEW.work_date:=a.work_date; IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.created_at:=now(); ELSE NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; NEW.updated_by:=auth.uid(); NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER a_treatment_before BEFORE INSERT OR UPDATE ON public.absence_treatments FOR EACH ROW EXECUTE FUNCTION public.treatment_before();
CREATE TRIGGER lock_treatments BEFORE INSERT OR UPDATE OR DELETE ON public.absence_treatments FOR EACH ROW EXECUTE FUNCTION public.enforce_period_lock();
CREATE TRIGGER audit_treatments AFTER INSERT OR UPDATE OR DELETE ON public.absence_treatments FOR EACH ROW EXECUTE FUNCTION public.audit_trg();
CREATE FUNCTION public.coverage_has_minute(c public.coverages,m time) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT m>=c.start_time AND m<c.end_time AND NOT(coalesce(m>=c.break_start AND m<c.break_end,false)) $$;
CREATE OR REPLACE FUNCTION public.coverage_conflict() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE identity_key text; BEGIN IF NEW.status='cancelada' THEN RETURN NEW; END IF; identity_key:=coalesce(NEW.day_worker_id,NEW.employee_id,NEW.supervisor_id)::text; PERFORM pg_advisory_xact_lock(hashtextextended(identity_key||NEW.work_date::text,0)); IF NOT EXISTS(SELECT 1 FROM public.posts WHERE id=NEW.post_id AND contract_id=NEW.contract_id) THEN RAISE EXCEPTION 'Posto e contrato incompatíveis.'; END IF; IF NEW.attendance_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.attendance a JOIN public.schedules s ON s.id=a.schedule_id WHERE a.id=NEW.attendance_id AND a.contract_id=NEW.contract_id AND a.work_date=NEW.work_date AND s.post_id=NEW.post_id) THEN RAISE EXCEPTION 'Ocorrência incompatível com a cobertura.'; END IF; IF NEW.supervisor_id IS NOT NULL AND NOT public.has_role(NEW.supervisor_id,'supervisor') THEN RAISE EXCEPTION 'Selecione um supervisor cadastrado.'; END IF; IF EXISTS(SELECT 1 FROM public.coverages c, generate_series(0,1439) m WHERE c.id<>NEW.id AND c.work_date=NEW.work_date AND c.status<>'cancelada' AND ((NEW.day_worker_id IS NOT NULL AND c.day_worker_id=NEW.day_worker_id) OR (NEW.employee_id IS NOT NULL AND c.employee_id=NEW.employee_id) OR (NEW.supervisor_id IS NOT NULL AND c.supervisor_id=NEW.supervisor_id)) AND public.coverage_has_minute(c,(time '00:00'+m*interval '1 minute')::time) AND public.coverage_has_minute(NEW,(time '00:00'+m*interval '1 minute')::time)) THEN RAISE EXCEPTION 'Conflito de horário: esta pessoa já possui cobertura sobreposta nesta data.'; END IF; IF NEW.employee_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.schedules s LEFT JOIN public.attendance a ON a.schedule_id=s.id, generate_series(0,1439) m WHERE s.employee_id=NEW.employee_id AND s.work_date=NEW.work_date AND public.coverage_has_minute(NEW,(time '00:00'+m*interval '1 minute')::time) AND (time '00:00'+m*interval '1 minute')::time>=s.start_time AND (time '00:00'+m*interval '1 minute')::time<s.end_time AND NOT coalesce((time '00:00'+m*interval '1 minute')::time>=s.break_start AND (time '00:00'+m*interval '1 minute')::time<s.break_end,false) AND (a.id IS NULL OR a.status='presente' OR (a.status='falta_parcial' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a.absent_intervals) i WHERE (time '00:00'+m*interval '1 minute')::time>=(i->>'start')::time AND (time '00:00'+m*interval '1 minute')::time<(i->>'end')::time)))) THEN RAISE EXCEPTION 'Conflito no posto de origem: registre o remanejamento como ausência parcial e resolva sua descoberta antes de fechar.'; END IF; NEW.created_by:=coalesce(auth.uid(),NEW.created_by); RETURN NEW; END $$;
CREATE FUNCTION public.pending_treatment_minutes(cid uuid,d1 date,d2 date) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.schedules s JOIN public.attendance a ON a.schedule_id=s.id CROSS JOIN generate_series(0,1439) m WHERE s.contract_id=cid AND s.work_date BETWEEN d1 AND d2 AND a.status IN ('falta_integral','falta_parcial','ferias','afastamento') AND (time '00:00'+m*interval '1 minute')::time>=s.start_time AND (time '00:00'+m*interval '1 minute')::time<s.end_time AND NOT coalesce((time '00:00'+m*interval '1 minute')::time>=s.break_start AND (time '00:00'+m*interval '1 minute')::time<s.break_end,false) AND (a.status<>'falta_parcial' OR EXISTS(SELECT 1 FROM jsonb_array_elements(a.absent_intervals) i WHERE (time '00:00'+m*interval '1 minute')::time>=(i->>'start')::time AND (time '00:00'+m*interval '1 minute')::time<(i->>'end')::time)) AND NOT EXISTS(SELECT 1 FROM public.coverages c WHERE c.contract_id=cid AND c.post_id=s.post_id AND c.work_date=s.work_date AND (c.attendance_id=a.id OR c.attendance_id IS NULL) AND c.status='realizada' AND public.coverage_has_minute(c,(time '00:00'+m*interval '1 minute')::time)) AND NOT EXISTS(SELECT 1 FROM public.absence_treatments t WHERE t.attendance_id=a.id AND t.active AND (time '00:00'+m*interval '1 minute')::time>=t.start_time AND (time '00:00'+m*interval '1 minute')::time<t.end_time) $$;
REVOKE ALL ON FUNCTION public.pending_treatment_minutes(uuid,date,date) FROM PUBLIC;
CREATE FUNCTION public.closing_treatment_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n bigint; BEGIN IF NEW.status='fechado' AND (TG_OP='INSERT' OR OLD.status<>'fechado') THEN n:=public.pending_treatment_minutes(NEW.contract_id,NEW.period_start,NEW.period_end); IF n>0 THEN RAISE EXCEPTION 'Fechamento bloqueado: % minuto(s) com tratamento pendente.',n; END IF; END IF; IF TG_OP='UPDATE' AND OLD.status='fechado' AND NEW.status='fechado' AND (NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.applied_discount IS DISTINCT FROM OLD.applied_discount) THEN RAISE EXCEPTION 'Reabra o período para alterar o fechamento.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER closing_treatment_guard BEFORE INSERT OR UPDATE ON public.closings FOR EACH ROW EXECUTE FUNCTION public.closing_treatment_guard();
CREATE FUNCTION public.list_coverage_supervisors() RETURNS TABLE(id uuid,full_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.full_name FROM public.profiles p WHERE auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid()) AND public.has_role(p.id,'supervisor') $$;
REVOKE ALL ON FUNCTION public.list_coverage_supervisors() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_coverage_supervisors() TO authenticated;